-- Operational source of truth (schema `oltp`). Written by the transaction
-- simulator, read by the ETL and by the read-only investigation tools.
--
-- Every table carries `updated_at`, stamped on insert and on every change.
-- The ETL uses it as its high-water mark.

CREATE SCHEMA IF NOT EXISTS oltp;

CREATE TABLE IF NOT EXISTS oltp.customers (
    customer_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- order_status: CREATED | PAID | CANCELLED | PARTIALLY_REFUNDED | REFUNDED
CREATE TABLE IF NOT EXISTS oltp.orders (
    order_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  BIGINT NOT NULL REFERENCES oltp.customers (customer_id),
    order_status TEXT NOT NULL,
    total_amount NUMERIC(12, 2) NOT NULL,
    currency     CHAR(3) NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- payment_status: CAPTURED | FAILED
CREATE TABLE IF NOT EXISTS oltp.payments (
    payment_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id       BIGINT NOT NULL REFERENCES oltp.orders (order_id),
    payment_status TEXT NOT NULL,
    amount         NUMERIC(12, 2) NOT NULL,
    paid_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- refund_status: PENDING | SUCCEEDED | FAILED
CREATE TABLE IF NOT EXISTS oltp.refunds (
    refund_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_id    BIGINT NOT NULL REFERENCES oltp.payments (payment_id),
    order_id      BIGINT NOT NULL REFERENCES oltp.orders (order_id),
    refund_status TEXT NOT NULL,
    refund_amount NUMERIC(12, 2) NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS orders_updated_at_idx ON oltp.orders (updated_at, order_id);
CREATE INDEX IF NOT EXISTS payments_updated_at_idx ON oltp.payments (updated_at, payment_id);
CREATE INDEX IF NOT EXISTS payments_order_idx ON oltp.payments (order_id);
CREATE INDEX IF NOT EXISTS refunds_updated_at_idx ON oltp.refunds (updated_at, refund_id);
CREATE INDEX IF NOT EXISTS refunds_order_idx ON oltp.refunds (order_id);

"""PostgreSQL access and schema management.

Two credentials exist. The application role owns every schema and is used by
the simulator, the ETL, and the repair executor. The read-only role can only
SELECT from the source, the analytics target, and the transform history; it
is the one handed to the investigation tools, so nothing an agent calls can
write, and nothing it calls can read DataTraceMind's own state.
"""

from __future__ import annotations

import json
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import date, datetime
from decimal import Decimal
from typing import Any

import psycopg
from psycopg import sql
from psycopg.conninfo import conninfo_to_dict
from psycopg.rows import dict_row
from psycopg.types.json import set_json_dumps

from datatracemind.config import SQL_DIR, get_settings

ANALYTICS_SCHEMA = "analytics"
STAGING_SCHEMA = "staging"
SOURCE_SCHEMA = "oltp"
READONLY_SCHEMAS = (SOURCE_SCHEMA, ANALYTICS_SCHEMA, "pipeline")
READONLY_STATEMENT_TIMEOUT_MS = 5000


def to_jsonable(value: Any) -> Any:
    """Convert database values into plain JSON types."""
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, dict):
        return {str(k): to_jsonable(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [to_jsonable(v) for v in value]
    return value


set_json_dumps(lambda obj: json.dumps(to_jsonable(obj)))


@contextmanager
def connect(*, readonly: bool = False, autocommit: bool = False) -> Iterator[psycopg.Connection]:
    """Open a connection that commits on success and rolls back on error."""
    settings = get_settings()
    if readonly:
        url = settings.readonly_database_url
        options = (
            "-c default_transaction_read_only=on "
            f"-c statement_timeout={READONLY_STATEMENT_TIMEOUT_MS}"
        )
    else:
        url = settings.database_url
        options = None
    with psycopg.connect(url, row_factory=dict_row, autocommit=autocommit, options=options) as conn:
        yield conn


def fetch_all(query: str | sql.Composable, params: Any = None, *, readonly: bool = False) -> list[dict]:
    with connect(readonly=readonly) as conn:
        return conn.execute(query, params).fetchall()


def fetch_one(query: str | sql.Composable, params: Any = None, *, readonly: bool = False) -> dict | None:
    with connect(readonly=readonly) as conn:
        return conn.execute(query, params).fetchone()


def execute(query: str | sql.Composable, params: Any = None) -> None:
    with connect() as conn:
        conn.execute(query, params)


def _read_sql(name: str) -> str:
    return (SQL_DIR / name).read_text()


def create_target_schema(conn: psycopg.Connection, schema: str) -> None:
    """Create the analytics tables in `schema` (idempotent)."""
    if schema not in (ANALYTICS_SCHEMA, STAGING_SCHEMA):
        raise ValueError(f"not a target schema: {schema}")
    conn.execute(_read_sql("target.sql").replace("__TARGET__", schema))


def rebuild_staging(conn: psycopg.Connection) -> None:
    """Drop and recreate the staging target so each validation starts empty."""
    conn.execute(sql.SQL("DROP SCHEMA IF EXISTS {} CASCADE").format(sql.Identifier(STAGING_SCHEMA)))
    create_target_schema(conn, STAGING_SCHEMA)


def _ensure_readonly_role(conn: psycopg.Connection) -> None:
    info = conninfo_to_dict(get_settings().readonly_database_url)
    role, password = info["user"], info["password"]
    exists = conn.execute("SELECT 1 FROM pg_roles WHERE rolname = %s", (role,)).fetchone()
    verb = sql.SQL("ALTER") if exists else sql.SQL("CREATE")
    conn.execute(
        sql.SQL("{} ROLE {} LOGIN PASSWORD {}").format(verb, sql.Identifier(role), sql.Literal(password))
    )
    for schema in READONLY_SCHEMAS:
        conn.execute(
            sql.SQL("GRANT USAGE ON SCHEMA {s} TO {r}; GRANT SELECT ON ALL TABLES IN SCHEMA {s} TO {r}").format(
                s=sql.Identifier(schema), r=sql.Identifier(role)
            )
        )


def ensure_schema() -> None:
    """Create every schema, table, and role that is missing (idempotent)."""
    with connect() as conn:
        # Concurrent callers (tests, API startup) would otherwise race on
        # CREATE SCHEMA IF NOT EXISTS, which is not atomic in PostgreSQL.
        conn.execute("SELECT pg_advisory_xact_lock(hashtext('dtm_schema'))")
        conn.execute(_read_sql("oltp.sql"))
        conn.execute(_read_sql("pipeline.sql"))
        create_target_schema(conn, ANALYTICS_SCHEMA)
        conn.execute(_read_sql("dtm.sql"))
        _ensure_readonly_role(conn)


def drop_all() -> None:
    """Remove all demo data and state. Used only by the demo reset."""
    with connect() as conn:
        conn.execute("SELECT pg_advisory_xact_lock(hashtext('dtm_schema'))")
        for schema in (SOURCE_SCHEMA, ANALYTICS_SCHEMA, STAGING_SCHEMA, "pipeline", "dtm"):
            conn.execute(sql.SQL("DROP SCHEMA IF EXISTS {} CASCADE").format(sql.Identifier(schema)))

"""Approved business contracts, loaded from `contracts/`.

Each contract is a Markdown file whose front matter is the machine-readable
form. Quality checks and source-derived metrics are computed from these
rules, never from the transformation they are checking.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path

import yaml

from datatracemind.config import CONTRACTS_DIR

# Contract name -> file. Agents may retrieve only these.
METRIC_CONTRACTS = {"net_revenue": "revenue.md"}
DATA_CONTRACTS = {"orders": "orders.md", "oltp_schema": "schemas/oltp.yaml"}


class ContractNotFound(LookupError):
    """No approved contract exists under that name."""


@dataclass(frozen=True)
class RevenueContract:
    version: int
    payment_statuses: tuple[str, ...]
    refund_statuses: tuple[str, ...]
    refund_amount_basis: str
    timezone: str
    tolerance: Decimal


def _front_matter(path: Path) -> dict:
    text = path.read_text()
    if not text.startswith("---"):
        raise ValueError(f"{path.name} has no front matter")
    _, block, _ = text.split("---", 2)
    return yaml.safe_load(block)


def read_contract_text(name: str, *, kind: str) -> tuple[str, str]:
    """Return (relative path, text) of an approved contract."""
    registry = METRIC_CONTRACTS if kind == "metric" else DATA_CONTRACTS
    if name not in registry:
        raise ContractNotFound(
            f"no approved {kind} contract named {name!r}; available: {sorted(registry)}"
        )
    path = CONTRACTS_DIR / registry[name]
    return f"contracts/{registry[name]}", path.read_text()


def load_revenue_contract() -> RevenueContract:
    meta = _front_matter(CONTRACTS_DIR / METRIC_CONTRACTS["net_revenue"])
    rules = meta["rules"]
    return RevenueContract(
        version=int(meta["version"]),
        payment_statuses=tuple(rules["payment_statuses_included"]),
        refund_statuses=tuple(rules["refund_statuses_subtracted"]),
        refund_amount_basis=rules["refund_amount_basis"],
        timezone=rules["business_timezone"],
        tolerance=Decimal(str(rules["reconciliation_tolerance"])),
    )


def load_source_schema_contract() -> dict[str, dict[str, str]]:
    """Expected source columns: {table: {column: type prefix}}."""
    return yaml.safe_load((CONTRACTS_DIR / DATA_CONTRACTS["oltp_schema"]).read_text())["tables"]

"""Schema of the transformation file (`order_revenue.yaml`).

The file is data, not code: the ETL interprets these fields and nothing else.
That is what makes a repair safe to run. A proposed patch is accepted only if
the patched file parses against this schema, so a patch can change which
rows qualify and how they are loaded, but cannot introduce SQL, code, or a
field the pipeline does not already understand.
"""

from __future__ import annotations

from typing import Annotated, Literal
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

import yaml
from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator

Identifier = Annotated[str, Field(pattern=r"^[a-z_][a-z0-9_]{0,62}$")]
StatusName = Annotated[str, Field(pattern=r"^[A-Z][A-Z0-9_]{1,39}$")]
StatusList = Annotated[list[StatusName], Field(max_length=10)]

MAX_SPEC_BYTES = 8_000


class SpecError(ValueError):
    """The transformation file is not valid."""


class _Strict(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


class SourceOrders(_Strict):
    amount_column: Identifier


class SourceSpec(_Strict):
    orders: SourceOrders


class FactOrdersSpec(_Strict):
    payment_join: Literal["left", "inner"]


class RevenueSpec(_Strict):
    timezone: str
    payment_statuses: StatusList
    refund_statuses: StatusList
    refund_amount_basis: Literal["refund_amount", "order_total"]

    @field_validator("timezone")
    @classmethod
    def _known_timezone(cls, value: str) -> str:
        try:
            ZoneInfo(value)
        except (ZoneInfoNotFoundError, ValueError) as exc:
            raise ValueError(f"unknown timezone {value!r}") from exc
        return value


class LoadSpec(_Strict):
    mode: Literal["replace_by_key", "append"]


class TransformSpec(_Strict):
    pipeline: Literal["order_revenue"]
    source: SourceSpec
    fact_orders: FactOrdersSpec
    revenue: RevenueSpec
    load: LoadSpec


def parse_spec(text: str) -> TransformSpec:
    """Parse and validate a transformation file."""
    if len(text.encode()) > MAX_SPEC_BYTES:
        raise SpecError(f"transformation file exceeds {MAX_SPEC_BYTES} bytes")
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise SpecError(f"transformation file is not valid YAML: {exc}") from exc
    if not isinstance(data, dict):
        raise SpecError("transformation file must be a YAML mapping")
    try:
        return TransformSpec.model_validate(data)
    except ValidationError as exc:
        problems = "; ".join(
            f"{'.'.join(str(p) for p in err['loc'])}: {err['msg']}" for err in exc.errors()
        )
        raise SpecError(f"transformation file is invalid: {problems}") from exc

"""Order-to-revenue transformation: source rows in, fact rows out.

Pure functions with no database access, so the same code runs in the live
pipeline, in staging validation, and in regression fixtures. Behaviour is
driven entirely by the TransformSpec.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal
from zoneinfo import ZoneInfo

from etl.transforms.spec import TransformSpec

ORDER_STATUSES = {"CREATED", "PAID", "CANCELLED", "PARTIALLY_REFUNDED", "REFUNDED"}
PAYMENT_STATUSES = {"CAPTURED", "FAILED"}
REFUND_STATUSES = {"PENDING", "SUCCEEDED", "FAILED"}

ZERO = Decimal("0.00")


@dataclass
class Bundle:
    """One order with all of its payments and refunds."""

    order: dict
    payments: list[dict] = field(default_factory=list)
    refunds: list[dict] = field(default_factory=list)


@dataclass
class TransformResult:
    fact_orders: list[dict] = field(default_factory=list)
    fact_payments: list[dict] = field(default_factory=list)
    fact_refunds: list[dict] = field(default_factory=list)
    rejects: list[dict] = field(default_factory=list)

    @property
    def row_count(self) -> int:
        return len(self.fact_orders) + len(self.fact_payments) + len(self.fact_refunds)


def _amount_problem(value: object) -> str | None:
    if value is None:
        return "amount is null"
    if not isinstance(value, Decimal):
        return f"amount is not numeric ({type(value).__name__})"
    if value < 0:
        return "amount is negative"
    return None


def _order_problem(order: dict) -> str | None:
    if order["order_status"] not in ORDER_STATUSES:
        return f"unknown order_status {order['order_status']!r}"
    currency = order["currency"]
    if not (isinstance(currency, str) and len(currency) == 3 and currency.isupper()):
        return f"invalid currency {currency!r}"
    return _amount_problem(order["amount"])


def transform_bundles(bundles: list[Bundle], spec: TransformSpec) -> TransformResult:
    """Turn order bundles into fact rows according to `spec`."""
    tz = ZoneInfo(spec.revenue.timezone)
    payment_statuses = set(spec.revenue.payment_statuses)
    refund_statuses = set(spec.revenue.refund_statuses)
    result = TransformResult()

    def reject(table: str, key: int, reason: str) -> None:
        result.rejects.append({"table": table, "id": key, "reason": reason})

    for bundle in bundles:
        order = bundle.order
        order_id = order["order_id"]
        problem = _order_problem(order)
        if problem:
            # Children take their currency from the order, so they cannot be
            # loaded without it.
            reject("orders", order_id, problem)
            for payment in bundle.payments:
                reject("payments", payment["payment_id"], "parent order rejected")
            for refund in bundle.refunds:
                reject("refunds", refund["refund_id"], "parent order rejected")
            continue

        currency = order["currency"]
        valid_payment_ids: set[int] = set()
        captured_amount = ZERO
        for payment in bundle.payments:
            problem = _amount_problem(payment["amount"])
            if payment["payment_status"] not in PAYMENT_STATUSES:
                problem = f"unknown payment_status {payment['payment_status']!r}"
            if problem:
                reject("payments", payment["payment_id"], problem)
                continue
            valid_payment_ids.add(payment["payment_id"])
            is_revenue = payment["payment_status"] in payment_statuses
            if is_revenue:
                captured_amount += payment["amount"]
            result.fact_payments.append(
                {
                    "payment_id": payment["payment_id"],
                    "order_id": order_id,
                    "payment_status": payment["payment_status"],
                    "amount": payment["amount"],
                    "currency": currency,
                    "paid_at": payment["paid_at"],
                    "revenue_date": payment["paid_at"].astimezone(tz).date(),
                    "is_revenue": is_revenue,
                }
            )

        for refund in bundle.refunds:
            problem = _amount_problem(refund["refund_amount"])
            if refund["refund_status"] not in REFUND_STATUSES:
                problem = f"unknown refund_status {refund['refund_status']!r}"
            elif refund["payment_id"] not in valid_payment_ids:
                problem = "refund references a payment that was not loaded"
            if problem:
                reject("refunds", refund["refund_id"], problem)
                continue
            is_subtracted = refund["refund_status"] in refund_statuses
            if not is_subtracted:
                subtracted = ZERO
            elif spec.revenue.refund_amount_basis == "order_total":
                subtracted = order["amount"]
            else:
                subtracted = refund["refund_amount"]
            result.fact_refunds.append(
                {
                    "refund_id": refund["refund_id"],
                    "payment_id": refund["payment_id"],
                    "order_id": order_id,
                    "refund_status": refund["refund_status"],
                    "refund_amount": refund["refund_amount"],
                    "currency": currency,
                    "created_at": refund["created_at"],
                    "revenue_date": refund["created_at"].astimezone(tz).date(),
                    "is_subtracted": is_subtracted,
                    "subtracted_amount": subtracted,
                }
            )

        # An inner join to payments produces no order row for an order that
        # has none; a left join keeps it.
        if spec.fact_orders.payment_join == "inner" and not bundle.payments:
            continue
        result.fact_orders.append(
            {
                "order_id": order_id,
                "customer_id": order["customer_id"],
                "order_status": order["order_status"],
                "total_amount": order["amount"],
                "currency": currency,
                "order_date": order["created_at"].astimezone(tz).date(),
                "payment_count": len(bundle.payments),
                "captured_amount": captured_amount,
                "created_at": order["created_at"],
                "updated_at": order["updated_at"],
            }
        )
    return result


def net_revenue_by_currency(result: TransformResult) -> dict[str, Decimal]:
    """Net revenue implied by a set of fact rows, per currency."""
    totals: dict[str, Decimal] = {}
    for row in result.fact_payments:
        if row["is_revenue"]:
            totals[row["currency"]] = totals.get(row["currency"], ZERO) + row["amount"]
    for row in result.fact_refunds:
        if row["is_subtracted"]:
            totals[row["currency"]] = totals.get(row["currency"], ZERO) - row["subtracted_amount"]
    return totals

"""Version history of the transformation file.

`etl/transforms/order_revenue.yaml` in the repository is the baseline. The
running pipeline reads the active row of `pipeline.transform_versions`, so a
deployment (a fault injected by the scenario lab, or an approved repair) is a
new row, and the previous content stays available for rollback and review.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from datetime import datetime

import psycopg

from datatracemind.config import REPO_ROOT, TRANSFORM_FILE
from datatracemind.db import connect


class NoActiveTransform(RuntimeError):
    """No transformation version is active; the pipeline cannot run."""


@dataclass(frozen=True)
class TransformVersion:
    version: int
    target_file: str
    content: str
    content_hash: str
    author: str
    message: str
    is_active: bool
    created_at: datetime


def content_hash(content: str) -> str:
    return hashlib.sha256(content.encode()).hexdigest()


def baseline_content() -> str:
    return (REPO_ROOT / TRANSFORM_FILE).read_text()


def register_version(
    conn: psycopg.Connection, content: str, *, author: str, message: str
) -> TransformVersion:
    """Record `content` as a new version and make it the active one."""
    conn.execute(
        "UPDATE pipeline.transform_versions SET is_active = false WHERE target_file = %s AND is_active",
        (TRANSFORM_FILE,),
    )
    row = conn.execute(
        """
        INSERT INTO pipeline.transform_versions (target_file, content, content_hash, author, message, is_active)
        VALUES (%s, %s, %s, %s, %s, true)
        RETURNING *
        """,
        (TRANSFORM_FILE, content, content_hash(content), author, message),
    ).fetchone()
    return TransformVersion(**row)


def get_active(conn: psycopg.Connection | None = None) -> TransformVersion:
    query = "SELECT * FROM pipeline.transform_versions WHERE target_file = %s AND is_active"
    if conn is None:
        with connect() as own:
            row = own.execute(query, (TRANSFORM_FILE,)).fetchone()
    else:
        row = conn.execute(query, (TRANSFORM_FILE,)).fetchone()
    if row is None:
        raise NoActiveTransform("no active transformation version; run the demo reset")
    return TransformVersion(**row)


def list_versions(conn: psycopg.Connection) -> list[TransformVersion]:
    rows = conn.execute(
        "SELECT * FROM pipeline.transform_versions WHERE target_file = %s ORDER BY version",
        (TRANSFORM_FILE,),
    ).fetchall()
    return [TransformVersion(**row) for row in rows]

"""Deterministic data-quality checks.

These decide whether the pipeline's output is trustworthy, and they decide
whether a repair passes. No model is involved. Every check is derived from an
approved contract or a structural invariant, never from the transformation
under test, and compares the target with the source snapshot the run read.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

import psycopg
from psycopg import sql

from etl.contract import RevenueContract, load_source_schema_contract
from etl.metrics import RevenueMetrics, reconcile, target_revenue

if TYPE_CHECKING:
    from etl.pipeline import SourceSnapshot

SAMPLE_SIZE = 10

# fact table -> (business key, snapshot attribute holding the source IDs)
FACT_KEYS = {
    "fact_orders": ("order_id", "order_ids"),
    "fact_payments": ("payment_id", "payment_ids"),
    "fact_refunds": ("refund_id", "refund_ids"),
}


@dataclass
class CheckResult:
    name: str
    passed: bool
    severity: str  # critical | high | medium
    observed: dict
    expected: str

    def as_dict(self) -> dict:
        return {
            "check_name": self.name,
            "passed": self.passed,
            "severity": self.severity,
            "observed_value": self.observed,
            "expected_condition": self.expected,
        }


def check_source_schema(conn: psycopg.Connection) -> CheckResult:
    """Source columns and types still match the schema contract."""
    expected = load_source_schema_contract()
    rows = conn.execute(
        "SELECT table_name, column_name, data_type FROM information_schema.columns WHERE table_schema = 'oltp'"
    ).fetchall()
    actual = {(r["table_name"], r["column_name"]): r["data_type"] for r in rows}
    missing, mismatched = [], []
    for table, columns in expected.items():
        for column, type_prefix in columns.items():
            found = actual.get((table, column))
            if found is None:
                missing.append(f"{table}.{column}")
            elif not found.startswith(type_prefix):
                mismatched.append({"column": f"{table}.{column}", "expected": type_prefix, "actual": found})
    known = {(t, c) for t, cols in expected.items() for c in cols}
    unexpected = sorted(f"{t}.{c}" for (t, c) in actual if t in expected and (t, c) not in known)
    return CheckResult(
        name="source_schema_contract",
        passed=not missing and not mismatched,
        severity="high",
        observed={"missing_columns": missing, "type_mismatches": mismatched, "unexpected_columns": unexpected},
        expected="every column in contracts/schemas/oltp.yaml exists in the source with the contracted type",
    )


def check_run_status(status: str, error_summary: str | None) -> CheckResult:
    return CheckResult(
        name="pipeline_run_succeeded",
        passed=status == "SUCCESS",
        severity="high",
        observed={"status": status, "error": error_summary},
        expected="the ETL run finishes with status SUCCESS",
    )


def _check_reconciliation(
    source: RevenueMetrics, target: RevenueMetrics, contract: RevenueContract
) -> CheckResult:
    report = reconcile(source, target, contract.tolerance)
    return CheckResult(
        name="net_revenue_reconciliation",
        passed=report.pop("reconciled"),
        severity="critical",
        observed=report,
        expected=(
            "net revenue derived from the source by the net_revenue contract equals "
            f"analytics daily_revenue.net_revenue per currency and per day within {contract.tolerance}"
        ),
    )


def _check_order_counts(source: RevenueMetrics, target: RevenueMetrics) -> CheckResult:
    currencies = sorted(set(source.by_currency) | set(target.by_currency))
    counts = {
        c: {
            "source_orders": int(source.by_currency.get(c, {}).get("order_count", 0)),
            "analytics_order_count": int(target.by_currency.get(c, {}).get("order_count", 0)),
        }
        for c in currencies
    }
    return CheckResult(
        name="order_count_reconciliation",
        passed=all(v["source_orders"] == v["analytics_order_count"] for v in counts.values()),
        severity="high",
        observed=counts,
        expected="daily_revenue.order_count totals equal the number of source orders per currency",
    )


def _check_completeness(
    conn: psycopg.Connection, schema: str, table: str, key: str, source_ids: set[int]
) -> CheckResult:
    query = sql.SQL("SELECT DISTINCT {} AS id FROM {}.{}").format(
        sql.Identifier(key), sql.Identifier(schema), sql.Identifier(table)
    )
    target_ids = {row["id"] for row in conn.execute(query)}
    missing = sorted(source_ids - target_ids)
    orphaned = sorted(target_ids - source_ids)
    return CheckResult(
        name=f"{table}_completeness",
        passed=not missing and not orphaned,
        severity="high",
        observed={
            "source_ids": len(source_ids),
            "analytics_ids": len(target_ids),
            "missing_in_analytics": len(missing),
            "missing_sample": missing[:SAMPLE_SIZE],
            "not_in_source": len(orphaned),
            "not_in_source_sample": orphaned[:SAMPLE_SIZE],
        },
        expected=f"every source {key} has a row in {table}, and every {table} row references a source {key}",
    )


def _check_unique_keys(conn: psycopg.Connection, schema: str) -> CheckResult:
    duplicates = {}
    for table, (key, _) in FACT_KEYS.items():
        query = sql.SQL(
            "SELECT {k} AS id, count(*) AS copies FROM {s}.{t} GROUP BY {k} HAVING count(*) > 1 ORDER BY {k}"
        ).format(k=sql.Identifier(key), s=sql.Identifier(schema), t=sql.Identifier(table))
        rows = conn.execute(query).fetchall()
        duplicates[table] = {
            "duplicated_keys": len(rows),
            "extra_rows": sum(r["copies"] - 1 for r in rows),
            "sample": [r["id"] for r in rows[:SAMPLE_SIZE]],
        }
    return CheckResult(
        name="unique_business_keys",
        passed=all(v["duplicated_keys"] == 0 for v in duplicates.values()),
        severity="high",
        observed=duplicates,
        expected="order_id, payment_id, and refund_id are each unique in their fact table",
    )


def _check_eligibility(conn: psycopg.Connection, schema: str, contract: RevenueContract) -> list[CheckResult]:
    """Fact rows are flagged as the contract says they should be."""
    payments = conn.execute(
        sql.SQL(
            """
            SELECT payment_status AS status, is_revenue AS counted, count(*) AS rows, sum(amount) AS amount
            FROM {}.fact_payments
            WHERE is_revenue <> (payment_status = ANY(%s))
            GROUP BY 1, 2 ORDER BY 1
            """
        ).format(sql.Identifier(schema)),
        (list(contract.payment_statuses),),
    ).fetchall()
    refunds = conn.execute(
        sql.SQL(
            """
            SELECT refund_status AS status, is_subtracted AS subtracted, count(*) AS rows,
                   sum(refund_amount) AS refund_amount
            FROM {}.fact_refunds
            WHERE is_subtracted <> (refund_status = ANY(%s))
            GROUP BY 1, 2 ORDER BY 1
            """
        ).format(sql.Identifier(schema)),
        (list(contract.refund_statuses),),
    ).fetchall()
    wrong_amount = conn.execute(
        sql.SQL(
            """
            SELECT count(*) AS rows, coalesce(sum(subtracted_amount - refund_amount), 0) AS over_subtracted
            FROM {}.fact_refunds
            WHERE is_subtracted AND subtracted_amount <> refund_amount
            """
        ).format(sql.Identifier(schema))
    ).fetchone()
    return [
        CheckResult(
            name="payment_revenue_eligibility",
            passed=not payments,
            severity="high",
            observed={"misclassified": payments},
            expected=f"a payment counts as revenue exactly when its status is in {list(contract.payment_statuses)}",
        ),
        CheckResult(
            name="refund_subtraction_eligibility",
            passed=not refunds and wrong_amount["rows"] == 0,
            severity="high",
            observed={
                "misclassified": refunds,
                "subtracted_amount_differs_from_refund_amount": wrong_amount,
            },
            expected=(
                f"a refund is subtracted exactly when its status is in {list(contract.refund_statuses)}, "
                "and the amount subtracted is refund_amount"
            ),
        ),
    ]


def _check_refund_ceiling(conn: psycopg.Connection, schema: str) -> CheckResult:
    rows = conn.execute(
        sql.SQL(
            """
            SELECT o.order_id, o.captured_amount, sum(r.subtracted_amount) AS subtracted
            FROM {s}.fact_orders o JOIN {s}.fact_refunds r ON r.order_id = o.order_id
            WHERE r.is_subtracted
            GROUP BY o.order_id, o.captured_amount
            HAVING sum(r.subtracted_amount) > o.captured_amount
            ORDER BY o.order_id
            """
        ).format(s=sql.Identifier(schema))
    ).fetchall()
    return CheckResult(
        name="refund_within_captured_amount",
        passed=not rows,
        severity="medium",
        observed={"orders_over_refunded": len(rows), "sample": rows[:SAMPLE_SIZE]},
        expected="refunds subtracted for an order never exceed the amount captured for it",
    )


def run_target_checks(
    conn: psycopg.Connection, schema: str, snapshot: SourceSnapshot, contract: RevenueContract
) -> list[CheckResult]:
    """All post-load checks for a successful run."""
    target = target_revenue(conn, schema)
    checks = [
        _check_reconciliation(snapshot.metrics, target, contract),
        _check_order_counts(snapshot.metrics, target),
    ]
    for table, (key, attr) in FACT_KEYS.items():
        checks.append(_check_completeness(conn, schema, table, key, getattr(snapshot, attr)))
    checks.append(_check_unique_keys(conn, schema))
    checks.extend(_check_eligibility(conn, schema, contract))
    checks.append(_check_refund_ceiling(conn, schema))
    return checks


def check_declared_status(status: str, checks: list[CheckResult]) -> CheckResult:
    """A run that reports SUCCESS while its output fails checks is a silent failure."""
    failed = [c.name for c in checks if not c.passed and c.severity in ("critical", "high")]
    return CheckResult(
        name="declared_status_consistent",
        passed=not (status == "SUCCESS" and failed),
        severity="critical",
        observed={"declared_status": status, "failed_checks": failed},
        expected="a run that declares SUCCESS has no failed critical or high checks",
    )

"""Common interface for fault scenarios.

A scenario introduces exactly one deterministic fault into the demo
environment. It also carries the answer key (`expected_symptoms`,
`ground_truth`) used to score a diagnosis. The answer key is for the
evaluator and the demo harness only: nothing in `datatracemind.tools`,
`datatracemind.agents`, or any prompt may import or read it.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass

import psycopg

from etl import transform_store


@dataclass
class InjectionContext:
    """What a scenario may touch while injecting its fault."""

    conn: psycopg.Connection

    def deploy_transform(self, old: str, new: str, *, author: str, message: str) -> None:
        """Deploy a new transformation version that differs by one replacement."""
        current = transform_store.get_active(self.conn).content
        if current.count(old) != 1:
            raise RuntimeError(f"cannot inject: expected exactly one {old!r} in the active transformation")
        transform_store.register_version(self.conn, current.replace(old, new), author=author, message=message)


class FaultScenario(ABC):
    scenario_id: str
    name: str
    description: str
    failure_type: str
    priority: str

    @abstractmethod
    def inject(self, context: InjectionContext) -> None:
        """Introduce one deterministic fault."""

    @abstractmethod
    def expected_symptoms(self) -> list[str]:
        """Evaluator-only: observations the fault should produce."""

    @abstractmethod
    def ground_truth(self) -> dict:
        """Evaluator-only: cause, expected failing checks, and expected repair."""

    def public_view(self) -> dict:
        """What the Scenario Lab page lists. Contains no answer key."""
        return {
            "scenario_id": self.scenario_id,
            "name": self.name,
            "description": self.description,
            "failure_type": self.failure_type,
            "priority": self.priority,
        }

"""The transformation as a pure function, and the schema that constrains it."""

from __future__ import annotations

from datetime import UTC, datetime
from decimal import Decimal

import pytest

from etl import transform_store
from etl.transforms.order_revenue import Bundle, net_revenue_by_currency, transform_bundles
from etl.transforms.spec import SpecError, parse_spec

BASELINE = transform_store.baseline_content()
AT = datetime(2026, 10, 1, 20, 0, tzinfo=UTC)  # 01:30 on 2 October in Asia/Kolkata


def order(order_id=1, status="PAID", amount="1000.00", currency="INR") -> dict:
    return {
        "order_id": order_id, "customer_id": 7, "order_status": status, "amount": Decimal(amount),
        "currency": currency, "created_at": AT, "updated_at": AT,
    }  # fmt: skip


def payment(payment_id=10, order_id=1, status="CAPTURED", amount="1000.00") -> dict:
    return {
        "payment_id": payment_id, "order_id": order_id, "payment_status": status,
        "amount": Decimal(amount), "paid_at": AT, "updated_at": AT,
    }  # fmt: skip


def refund(refund_id=100, status="SUCCEEDED", amount="1000.00", payment_id=10, order_id=1) -> dict:
    return {
        "refund_id": refund_id, "payment_id": payment_id, "order_id": order_id, "refund_status": status,
        "refund_amount": Decimal(amount), "created_at": AT, "updated_at": AT,
    }  # fmt: skip


def spec(**replacements: str):
    text = BASELINE
    for old, new in replacements.items():
        assert text.count(old) == 1
        text = text.replace(old, new)
    return parse_spec(text)


def net(bundles, transform_spec) -> Decimal:
    return net_revenue_by_currency(transform_bundles(bundles, transform_spec)).get("INR", Decimal(0))


def test_partial_refund_subtracts_the_refunded_amount_only():
    bundle = Bundle(order(), [payment()], [refund(amount="250.00")])
    assert net([bundle], spec()) == Decimal("750.00")


def test_pending_and_failed_refunds_are_not_subtracted():
    bundle = Bundle(order(), [payment()], [refund(100, "PENDING"), refund(101, "FAILED")])
    assert net([bundle], spec()) == Decimal("1000.00")


def test_failed_payment_is_not_revenue():
    bundle = Bundle(order(status="CANCELLED"), [payment(status="FAILED")])
    result = transform_bundles([bundle], spec())
    assert net_revenue_by_currency(result) == {}
    assert result.fact_payments[0]["is_revenue"] is False
    assert result.fact_orders[0]["captured_amount"] == Decimal("0.00")


def test_refund_filter_naming_an_unknown_status_subtracts_nothing():
    bundle = Bundle(order(), [payment()], [refund()])
    faulty = spec(**{"refund_statuses: [SUCCEEDED]": "refund_statuses: [COMPLETED]"})
    assert net([bundle], faulty) == Decimal("1000.00")
    assert net([bundle], spec()) == Decimal("0.00")


def test_order_total_basis_over_subtracts_a_partial_refund():
    bundle = Bundle(order(), [payment()], [refund(amount="250.00")])
    faulty = spec(**{"refund_amount_basis: refund_amount": "refund_amount_basis: order_total"})
    assert net([bundle], faulty) == Decimal("0.00")


def test_left_join_keeps_unpaid_orders_and_inner_join_drops_them():
    unpaid = Bundle(order(order_id=2, status="CREATED"))
    assert len(transform_bundles([unpaid], spec()).fact_orders) == 1
    inner = spec(**{"payment_join: left": "payment_join: inner"})
    assert transform_bundles([unpaid], inner).fact_orders == []


def test_rows_are_dated_in_the_business_timezone():
    result = transform_bundles([Bundle(order(), [payment()], [refund()])], spec())
    assert result.fact_payments[0]["revenue_date"].isoformat() == "2026-10-02"
    assert result.fact_orders[0]["order_date"].isoformat() == "2026-10-02"


def test_unknown_status_is_rejected_not_guessed():
    bundle = Bundle(order(), [payment()], [refund(status="PAYMENT_REVERSED")])
    result = transform_bundles([bundle], spec())
    assert result.fact_refunds == []
    assert result.rejects == [{"table": "refunds", "id": 100, "reason": "unknown refund_status 'PAYMENT_REVERSED'"}]


def test_null_amount_rejects_the_order_and_its_children():
    bad = order()
    bad["amount"] = None
    result = transform_bundles([Bundle(bad, [payment()], [refund()])], spec())
    assert result.row_count == 0
    assert [r["table"] for r in result.rejects] == ["orders", "payments", "refunds"]


@pytest.mark.parametrize(
    "old, new",
    [
        ("mode: replace_by_key", "mode: replace_by_key\n  post_load_sql: DROP TABLE oltp.orders"),
        ("payment_join: left", "payment_join: cross"),
        ("amount_column: total_amount", 'amount_column: "total_amount; DROP TABLE oltp.orders"'),
        ("refund_statuses: [SUCCEEDED]", "refund_statuses: ['SUCCEEDED'' OR 1=1']"),
        ("timezone: Asia/Kolkata", "timezone: Mars/Olympus"),
        ("pipeline: order_revenue", "pipeline: something_else"),
    ],
)
def test_spec_rejects_anything_outside_the_allowed_shape(old, new):
    assert BASELINE.count(old) == 1
    with pytest.raises(SpecError):
        parse_spec(BASELINE.replace(old, new))


def test_spec_rejects_non_mapping_and_oversized_files():
    with pytest.raises(SpecError):
        parse_spec("- just\n- a list\n")
    with pytest.raises(SpecError):
        parse_spec(BASELINE + "#" * 9000)

"""The ETL worker: runs the pipeline on a schedule and feeds the monitor."""

from __future__ import annotations

import logging
import threading
from collections.abc import Callable

from datatracemind.config import get_settings
from datatracemind.monitoring import monitor
from etl import pipeline

logger = logging.getLogger(__name__)


class EtlWorker:
    """Background thread: one ETL run every few seconds, then detection."""

    def __init__(self, on_incident: Callable[[str], None] | None = None) -> None:
        self._thread: threading.Thread | None = None
        self._stop = threading.Event()
        self._on_incident = on_incident

    @property
    def running(self) -> bool:
        return self._thread is not None and self._thread.is_alive()

    def start(self) -> None:
        if self.running:
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._run, name="etl-worker", daemon=True)
        self._thread.start()

    def stop(self) -> None:
        if not self.running:
            return
        self._stop.set()
        self._thread.join(timeout=30)
        self._thread = None

    def _run(self) -> None:
        interval = get_settings().etl_interval_s
        while not self._stop.wait(interval):
            try:
                result = pipeline.run_once(trigger="schedule")
                incident_id = monitor.evaluate_run(result) or monitor.evaluate_freshness()
                if incident_id and self._on_incident:
                    self._on_incident(incident_id)
            except Exception:
                # run_once records pipeline failures itself; anything that
                # reaches here is infrastructure (for example a reset in
                # progress). Log it and try again on the next tick.
                logger.exception("ETL worker tick failed")

"""FastAPI service: demo controls, metrics, incidents, and the repair lifecycle.

Lifecycle rules are enforced by the modules the routes call, never by the
routes or the frontend. A route only translates their refusals into HTTP
status codes.
"""

from __future__ import annotations

import hmac
import logging
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request
from fastapi.responses import JSONResponse

